"""reference.ReferencePlayer: 5 greedy act calls pass the Agent check via the replay double."""

from rllab.core import Agent
from rllab.reference import ReferencePlayer

SYMBOL = "reference.ReferencePlayer"


def test_samples_follow_the_schema(codec):
    codec.assert_samples_valid(SYMBOL)


def test_recording_passes_the_agent_check(codec, tmp_path):
    fake = codec.fake("core.Agent")
    recording = codec.sample(SYMBOL, "greedy_5", fake.AgentRecording)
    acts = recording.acts()
    assert len(acts) == 5
    assert not any(call.explore for call in acts)
    fake.check_agent(fake.ReplayAgent(recording), recording, tmp_path)


def test_reference_player_is_an_agent():
    assert Agent in ReferencePlayer.__mro__

